import { CommonModule } from '@angular/common';
import { Component, inject, OnInit, signal } from '@angular/core';
import {
  IonBackButton,
  IonButton,
  IonButtons,
  IonCard,
  IonCardContent,
  IonCardHeader,
  IonCardTitle,
  IonContent,
  IonHeader,
  IonItem,
  IonLabel,
  IonList,
  IonNote,
  IonRefresher,
  IonRefresherContent,
  IonSegment,
  IonSegmentButton,
  IonTitle,
  IonToolbar,
  RefresherCustomEvent,
} from '@ionic/angular/standalone';
import { getRoutePath } from '../app.routes';
import { WidgetSyncService } from '../common/widget/widget-sync.service';
import { WidgetVerse } from '../common/widget/widget-sync.plugin';

@Component({
  selector: 'app-tools',
  templateUrl: './tools.page.html',
  styleUrls: ['./tools.page.scss'],
  standalone: true,
  imports: [
    CommonModule,
    IonHeader,
    IonToolbar,
    IonTitle,
    IonContent,
    IonButtons,
    IonBackButton,
    IonCard,
    IonCardHeader,
    IonCardTitle,
    IonCardContent,
    IonButton,
    IonList,
    IonItem,
    IonLabel,
    IonNote,
    IonRefresher,
    IonRefresherContent,
    IonSegment,
    IonSegmentButton,
  ],
})
export class ToolsPage implements OnInit {
  private readonly widgetSyncService = inject(WidgetSyncService);

  readonly searchRoutePath = getRoutePath('search');
  readonly widgetVerses = signal<WidgetVerse[]>([]);
  readonly selectedTagId = signal<number | null>(null);
  readonly refreshIntervalHours = signal<number>(12);
  readonly isLoading = signal<boolean>(false);
  readonly activeTab = signal<'widget' | 'errors'>('widget');

  async ngOnInit() {
    await this.loadWidgetData();
  }

  async loadWidgetData() {
    this.isLoading.set(true);
    try {
      const [verses, settings] = await Promise.all([
        this.widgetSyncService.getSyncedVerses(),
        this.widgetSyncService.getWidgetSettings(),
      ]);
      this.widgetVerses.set(verses);
      this.selectedTagId.set(settings.selectedTagId);
      this.refreshIntervalHours.set(settings.refreshIntervalHours);
    } finally {
      this.isLoading.set(false);
    }
  }

  async handleRefresh(event: RefresherCustomEvent) {
    await this.loadWidgetData();
    event.target.complete();
  }

  getVerseReference(verse: WidgetVerse): string {
    if (verse.end_verse && verse.end_verse !== verse.start_verse) {
      return `${verse.book} ${verse.chapter}:${verse.start_verse}-${verse.end_verse}`;
    }
    return `${verse.book} ${verse.chapter}:${verse.start_verse}`;
  }

  getPlainTextContent(verse: WidgetVerse): string {
    let text = verse.content;
    // Remove <sup>number</sup> tags
    text = text.replace(/<sup>\s*\d+\s*<\/sup>\s*/g, '');
    // Remove any remaining HTML tags
    text = text.replace(/<[^>]+>/g, '');
    // Remove standalone verse numbers
    text = text.replace(/^\d+\s+/, '');
    text = text.replace(/([.!?])\s*\d+\s+/g, '$1 ');
    // Clean up multiple spaces
    text = text.replace(/\s+/g, ' ');
    return text.trim();
  }

  throwError() {
    throw new Error('Test error for BugSplat - this is intentional for testing purposes');
  }

  triggerUnhandledPromiseRejection() {
    Promise.reject(new Error('Test unhandled promise rejection for error handling - this is intentional for testing purposes'));
  }
}
